package negocio;
import java.time.LocalDateTime;
public class SolicitudComunidad { private long id,convocatoriaId,perfilSolicitanteId,version; private EstadoSolicitudComunidad estado=EstadoSolicitudComunidad.PENDIENTE; private String mensaje; private LocalDateTime fechaSolicitud,fechaContacto,fechaResolucion,fechaActualizacion;
 public long getId(){return id;} public void setId(long v){id=v;} public long getConvocatoriaId(){return convocatoriaId;} public void setConvocatoriaId(long v){convocatoriaId=v;} public long getPerfilSolicitanteId(){return perfilSolicitanteId;} public void setPerfilSolicitanteId(long v){perfilSolicitanteId=v;} public long getVersion(){return version;} public void setVersion(long v){version=v;} public EstadoSolicitudComunidad getEstado(){return estado;} public void setEstado(EstadoSolicitudComunidad v){estado=v;} public String getMensaje(){return mensaje;} public void setMensaje(String v){mensaje=v;} public LocalDateTime getFechaSolicitud(){return fechaSolicitud;} public void setFechaSolicitud(LocalDateTime v){fechaSolicitud=v;} public LocalDateTime getFechaContacto(){return fechaContacto;} public void setFechaContacto(LocalDateTime v){fechaContacto=v;} public LocalDateTime getFechaResolucion(){return fechaResolucion;} public void setFechaResolucion(LocalDateTime v){fechaResolucion=v;} public LocalDateTime getFechaActualizacion(){return fechaActualizacion;} public void setFechaActualizacion(LocalDateTime v){fechaActualizacion=v;} public void validar(long perfilCreadorId){if(convocatoriaId<=0||perfilSolicitanteId<=0||estado==null)throw new IllegalArgumentException("La solicitud es incompleta.");if(perfilSolicitanteId==perfilCreadorId)throw new IllegalArgumentException("No podés solicitar unirte a tu propia convocatoria.");if(mensaje!=null&&mensaje.trim().length()>300)throw new IllegalArgumentException("El mensaje no puede superar 300 caracteres.");}}
